const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const i = $input.first().json || {};
let caso = null;
try { caso = $('Teste: rodar cenário').first().json; } catch (e) { caso = null; }
if (caso) {
  const corpo = caso.body || {};
  return [{ json: { message_id: String(i.ultima_mensagem || ''), teste: true, limpar: corpo.limpar !== false, caso_id: String(corpo.caso_id || ''), valido: UUID.test(String(i.ultima_mensagem || '')) } }];
}
const b = i.body || {};
const id = String(b.message_id || i.message_id || '');
return [{ json: { message_id: id, teste: false, limpar: false, caso_id: '', valido: UUID.test(id) } }];

const g = $('Conferir se o agente deve responder').first().json;
let deb = null;
try { deb = $('Debounce de novo (depois da espera)').first().json; } catch (e) { deb = null; }
if (!deb || !Array.isArray(deb.mensagens)) deb = $('Debounce: sou a última mensagem?').first().json;
const msgs = Array.isArray(deb.mensagens) ? deb.mensagens : [];

if (msgs.length === 0) {
  const norm = $('Entrada normalizada').first().json;
  return [{ json: { ordem: 0, id: norm.message_id, tipo: g.tipo || 'text', corpo: '', media_id: '', execucao_id: g.execucao_id, conversation_id: g.conversation_id, vazia: false } }];
}

return msgs.map((m, k) => ({ json: { ordem: k, id: m.id, tipo: m.tipo, corpo: m.corpo || '', media_id: m.media_id || '', execucao_id: g.execucao_id, conversation_id: g.conversation_id, vazia: false } }));

const orig = $('Separar mensagens do grupo').item.json;
const t = String(($input.first().json || {}).text || '').trim();
return [{ json: { ordem: orig.ordem, id: orig.id, execucao_id: orig.execucao_id, ok: t.length > 0, texto: t.length > 0 ? t : '[áudio que não consegui ouvir: peça para o cliente escrever]' } }];

const orig = $('Tipo da mensagem').item.json;
const legenda = String(orig.corpo || '').trim();
let texto = '[o cliente enviou uma imagem/foto em anexo]';
if (legenda) {
  texto = `${legenda}\n[anexo: imagem/foto enviada junto com a mensagem acima]`;
}
return [{ json: { ordem: orig.ordem, texto: texto } }];

const orig = $('Tipo da mensagem').item.json;
const legenda = String(orig.corpo || '').trim();
let texto = '[o cliente enviou um documento PDF/arquivo em anexo]';
if (legenda) {
  texto = `${legenda}\n[anexo: documento/arquivo enviado junto com a mensagem acima]`;
}
return [{ json: { ordem: orig.ordem, texto: texto } }];

const itens = $input.all().map((x) => x.json).sort((a, b) => a.ordem - b.ordem);
const ehVazia = itens.some(x => x.vazia === true);
if (ehVazia) {
  return [{ json: { texto_cliente: '[grupo_vazio]', quantidade_mensagens: 0, vazia: true } }];
}
let texto = itens.map((x) => String(x.texto || '').trim()).filter(Boolean).join('\n').slice(0, 2500);

// Normalização de medidas: 50x50, 50×50, 50X50, 50*50, 50 por 50 -> 50x50
texto = texto.replace(/(\d+)\s*([×X\*]|\bpor\b)\s*(\d+)/gi, '$1x$3');

// Normalização de abreviações de quantidade: "400 uni", "400 und", "400 unids", "400 un" -> "400 unidades"
texto = texto.replace(/(\d+)\s*(uni|und|unid|unids|unis)\b/gi, '$1 unidades');

return [{ json: { texto_cliente: texto || '[mensagem vazia]', quantidade_mensagens: itens.length, vazia: false } }];

const g = $('Conferir se o agente deve responder').first().json;
const texto = String($('Texto único do cliente').first().json.texto_cliente || '');
const OBJECAO = /(\bcaro\b|\bcara\b|car[ií]ssim|desconto|abatiment|abaixa|abaixar|mais barat|menos que|melhor pre[cç]o|[uú]ltimo pre[cç]o|pre[cç]o final|concorr|outro lugar|achei mais|n[aã]o compensa|reclam|absurd|negoci|puxado|vou pensar)/i;
const forte = OBJECAO.test(texto);
return [{ json: { modelo: forte ? (g.modelo_forte || 'gemini-2.5-pro') : (g.modelo_padrao || 'gemini-2.5-flash'), modelo_forte: forte } }];

const r = $input.first() ? ($input.first().json || {}) : {};
const teste = $('Entrada normalizada').first().json.teste === true;
const texto = r.erro || r.error ? '' : String(r.texto || r.output || r.text || '').trim();
const partes = texto.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
const curtas = [];
for (const p of partes) {
  if (p.length <= 280) { curtas.push(p); continue; }
  const frases = p.match(/[^.!?]+[.!?]*\s*/g) || [p];
  let atual = '';
  for (const f of frases) {
    if ((atual + f).length > 280 && atual) { curtas.push(atual.trim()); atual = f; } else { atual += f; }
  }
  if (atual.trim()) curtas.push(atual.trim());
}
const finais = curtas.slice(0, 3);
if (curtas.length > 3) finais[2] = (finais[2] + ' ' + curtas.slice(3).join(' ')).trim();
if (!finais.length) return [{ json: { vazio: true, texto: '', atraso: 1, i: 0, erro: !!(r.erro || r.error) } }];
return finais.map((t, i) => ({ json: { vazio: false, texto: t, atraso: teste ? 1 : Math.min(6, Math.max(1, Math.round(1 + t.length / 45))), i: i, erro: false } }));

